#!/usr/bin/env python3
"""Builds database/meta/search_vocabulary.csv – the e-commerce / sourcing / finance words the search box understands (R-G_CORE-100).
Each row: term, maps_to (the system's own words), kind, target_url (the screen it opens). Run again after editing the groups below."""
import csv, os
G = {}
def add(url, maps, *terms):
    for t in terms:
        for x in [s.strip() for s in t.split('|') if s.strip()]:
            G.setdefault(x.lower(), (maps, url))

